INSERT INTO "mastra_messages" ("id","thread_id","content","role","type","createdAt","resourceId") VALUES ('1b0a6f5c-9644-4124-b6c1-ae83158a7465','c2466a74-8c9b-4ece-8e7e-969a549399a5','{"format":2,"parts":[{"type":"reasoning","reasoning":"The user wants the full rebrand kickoff email. That''s \"Rebrand kickoff\" from Raj Mehta, Sep 21, id WyJJTkJPWCIsIjEwMDAiLDQxMF0.\n\nGet it.","details":[{"type":"text","text":"The user wants the full rebrand kickoff email. That''s \"Rebrand kickoff\" from Raj Mehta, Sep 21, id WyJJTkJPWCIsIjEwMDAiLDQxMF0.\n\nGet it."}],"createdAt":1795579825826},{"type":"tool-invocation","toolInvocation":{"state":"result","result":{"id":"WyJJTkJPWCIsIjEwMDAiLDQxMF0","from":"Raj Mehta","to":["ana@demo.trymetis.email"],"subject":"Rebrand kickoff","date":"Mon Sep 21 2026 09:15:00 GMT+0000 (Coordinated Universal Time)","hasContent":true,"body":"Hi Ana,\r\n\r\nWe agreed to start the rebrand on October 5. Can you send me the\r\nmoodboard by Friday, and confirm whether Tomás can join the first review?\r\n\r\nThanks,\r\nRaj"},"toolCallId":"call_resp_01a210e5-c3de-7acd-aa78-b38fe9a28383_0","toolName":"getEmail","args":{"id":"WyJJTkJPWCIsIjEwMDAiLDQxMF0","mailboxId":"2509b3b7-2ea9-5861-9415-92dd8cc89134"}},"updatedAt":1795579825835},{"type":"step-start","createdAt":1795579825837,"model":"openai-compatible.chat/metis/demo"},{"type":"text","text":"**From:** Raj Mehta <raj@demo.trymetis.email>\n**To:** ana@demo.trymetis.email\n**Date:** Mon 21 Sep 2026, 09:15 UTC\n**Subject:** Rebrand kickoff\n**Mailbox:** ana@demo.trymetis.email\n\n> Hi Ana,\n>\n> We agreed to start the rebrand on October 5. Can you send me the\n> moodboard by Friday, and confirm whether Tomás can join the first review?\n>\n> Thanks,\n> Raj\n\nTwo asks in it: the **moodboard by Friday (25 Sep)** and confirmation on whether **Tomás can join the first review** — with work starting **5 Oct**. Both are long past now; the nearest reply in the mailbox is your \"Moodboard for Aozora\" sent 15 Sep, which predates it, so nothing in the mailbox answers this one.","createdAt":1795579828888}],"metadata":{"modelId":"metis/demo","provider":"openai-compatible.chat"},"content":"**From:** Raj Mehta <raj@demo.trymetis.email>\n**To:** ana@demo.trymetis.email\n**Date:** Mon 21 Sep 2026, 09:15 UTC\n**Subject:** Rebrand kickoff\n**Mailbox:** ana@demo.trymetis.email\n\n> Hi Ana,\n>\n> We agreed to start the rebrand on October 5. Can you send me the\n> moodboard by Friday, and confirm whether Tomás can join the first review?\n>\n> Thanks,\n> Raj\n\nTwo asks in it: the **moodboard by Friday (25 Sep)** and confirmation on whether **Tomás can join the first review** — with work starting **5 Oct**. Both are long past now; the nearest reply in the mailbox is your \"Moodboard for Aozora\" sent 15 Sep, which predates it, so nothing in the mailbox answers this one."}','assistant','v2','2026-11-25T04:10:25.826Z','f0c4be98-b2fd-59d7-b11e-c921e7d22615');
