In":true},{"key":"updates","builtIn":true},{"key":"newsletter","builtIn":true},{"key":"personal","builtIn":true},{"key":"promotional","builtIn":true},{"key":"social","builtIn":true},{"key":"custom:clients","builtIn":false}]},"toolCallId":"call_resp_01a210e8-8f16-7164-9e2f-f8a83ffca20f_0","toolName":"listLabels","args":{}},"updatedAt":1795580009966},{"type":"step-start","createdAt":1795580009968,"model":"openai-compatible.chat/metis/demo"},{"type":"text","text":"**9 labels — 8 built-in, 1 custom:**\n\n**Built-in**\n- `action_required`\n- `work`\n- `transactions`\n- `updates`\n- `newsletter`\n- `personal`\n- `promotional`\n- `social`\n\n**Custom**\n- `custom:clients`\n\nThese keys are workspace-wide and the only valid ones for applying or clearing a label — note the custom one keeps its `custom:` prefix when you use it. If you want to tag anything from the threads we''ve been through, sensible fits would be `transactions` on the Konkan Bank debits and the Ledgerline invoices, and `action_required` on the Brightloom A-42 order (no tracking, no delivery) and the two phishing messages in spam.","createdAt":1795580012918}],"metadata":{"modelId":"metis/demo","provider":"openai-compatible.chat"},"content":"**9 labels — 8 built-in, 1 custom:**\n\n**Built-in**\n- `action_required`\n- `work`\n- `transactions`\n- `updates`\n- `newsletter`\n- `personal`\n- `promotional`\n- `social`\n\n**Custom**\n- `custom:clients`\n\nThese keys are workspace-wide and the only valid ones for applying or clearing a label — note the custom one keeps its `custom:` prefix when you use it. If you want to tag anything from the threads we''ve been through, sensible fits would be `transactions` on the Konkan Bank debits and the Ledgerline invoices, and `action_required` on the Brightloom A-42 order (no tracking, no delivery) and the two phishing messages in spam."}','assistant','v2','2026-11-25T04:13:25.584Z','f0c4be98-b2fd-59d7-b11e-c921e7d22615');
