INSERT INTO "mastra_messages" ("id","thread_id","content","role","type","createdAt","resourceId") VALUES ('0400c061-5fd4-4ffa-8726-69ab7e001df8','c2466a74-8c9b-4ece-8e7e-969a549399a5','{"format":2,"parts":[{"type":"reasoning","reasoning":"Need workspace member tools. Search tools for \"list workspace members\".","details":[{"type":"text","text":"Need workspace member tools. Search tools for \"list workspace members\"."}],"createdAt":1795580231587},{"type":"tool-invocation","toolInvocation":{"state":"result","result":{"results":[{"name":"listWorkspaceMembers","description":"List the people in this workspace with their memberId, name, email address, and role. Use when the user names a colleague without an inline <@membe...","score":9.02},{"name":"listInvites","description":"List the pending invitations to join this workspace. Workspace owners and admins only.","score":6.23},{"name":"listPins","description":"List the drive folders you pinned for quick access in this workspace.","score":5.75},{"name":"listThemes","description":"List the themes this workspace can use (built-in, the instance''s own and the workspace''s custom ones) and which one it uses now.","score":5.74},{"name":"listSignatures","description":"List this workspace''s email signatures and its mail footer, and, for a mailbox, its signatures and your own.","score":5.45}],"loaded":["listWorkspaceMembers","listInvites","listPins","listThemes","listSignatures"],"message":"Found and loaded 5 tool(s): listWorkspaceMembers, listInvites, listPins, listThemes, listSignatures. They are available on your next turn — call them directly."},"toolCallId":"call_resp_01a210eb-b4f9-7210-9b9a-9984ab740906_0","toolName":"search_tools","args":{"query":"list workspace members"}},"updatedAt":1795580231589},{"type":"step-start","createdAt":1795580231591,"model":"openai-compatible.chat/metis/demo"},{"type":"tool-invocation","toolInvocation":{"state":"result","result":{"count":1,"members":[{"memberId":"f0c4be98-b2fd-59d7-b11e-c921e